s2_num = (a*a + b*b) * dB - 2*a*b * nB
if s2_num % dB != 0:
    # s^2 must be integer
    return (False, None)
s2 = s2_num // dB
if s2 <= 0:
    return (False, None)
s = int(math.isqrt(s2))
if s * s != s2:
    # ensure exact perfect square
    return (False, None)
